function normalizeModelName(name: string): string {
  let n = name.trim().toLowerCase();
  for (const prefix of ["openrouter/", "azure/", "bedrock/"]) {
    if (n.startsWith(prefix)) n = n.slice(prefix.length);
  }
  return n;
}

export interface CostBreakdown {
  inputCost: number;
  outputCost: number;
  totalCost: number;
}

export function calculateCost(
  model: string,
  inputTokens: number,
  outputTokens: number,
  cachedTokens = 0,
  reasoningTokens = 0,
): CostBreakdown | null {
  const normalized = normalizeModelName(model);
  const rates = PRICING[model] ?? PRICING[normalized] ?? PRICING[normalized.toLowerCase()];
  if (!rates) return null;
  const cacheableInput = Math.max(0, inputTokens - cachedTokens);
  const inputCost = cacheableInput * (rates.input ?? 0);
  const outputCost = outputTokens * (rates.output ?? 0);
  const cacheReadCost = cachedTokens * (rates.cache_read ?? 0);
  const reasoningCost = reasoningTokens * (rates.reasoning ?? 0);
  const total = inputCost + outputCost + cacheReadCost + reasoningCost;
  return {
    inputCost: Number((inputCost + cacheReadCost).toFixed(8)),
    outputCost: Number((outputCost + reasoningCost).toFixed(8)),
    totalCost: Number(total.toFixed(8)),
  };
}
